history.replaceState(null,'','/fixture_author/status/100');
window.qa={messages:[],contacts:[{handle:'demo_friend',displayName:'林一 · 开源工具',note:'经常讨论开源的朋友',pinned:true},{handle:'reader_demo',displayName:'读者阿夏',note:'产品讨论'},{handle:'maker_demo',displayName:'独立开发日常',note:'一起写代码'}]};
window.chrome={runtime:{sendMessage:async m=>{window.qa.messages.push(m);let data={};if(m.type==='contacts-page')data={items:qa.contacts.filter(c=>`${c.handle} ${c.displayName} ${c.note}`.includes(m.query||''))};if(m.type==='contacts-reply')document.getElementById('result').textContent='已记录回复对象：@'+m.contact.handle;return{ok:true,data};}}};
document.getElementById('send-success').onclick=()=>{const editor=document.querySelector('[data-testid=tweetTextarea_0]'),text=editor.innerText,id=String(Date.now());if(!text.trim())return;const article=document.createElement('article');article.dataset.testid='tweet';const a=document.createElement('a');a.href='/fixture_me/status/'+id;const time=document.createElement('time');time.dateTime=new Date().toISOString();time.textContent='刚刚';a.append(time);const body=document.createElement('div');body.dataset.testid='tweetText';body.textContent=text;article.append(a,body);document.getElementById('receipts').append(article);editor.replaceChildren(document.createElement('div'));};
document.getElementById('theme').onclick=()=>document.body.classList.toggle('dark');
const script=document.createElement('script');script.src='/dist/chrome/mentions.js';document.body.append(script);
